1	package com.orech.patcher
2	
3	import android.content.Context
4	import com.android.tools.smali.baksmali.Baksmali
5	import com.android.tools.smali.baksmali.BaksmaliOptions
6	import com.android.tools.smali.dexlib2.DexFileFactory
7	import com.android.tools.smali.dexlib2.Opcodes
8	import com.android.tools.smali.smali.Smali
9	import com.android.tools.smali.smali.SmaliOptions
10	import com.reandroid.apk.ApkModule
11	import com.reandroid.archive.ByteInputSource
12	import com.reandroid.arsc.chunk.xml.ResXmlDocument
13	import com.reandroid.arsc.chunk.xml.ResXmlAttribute
14	import com.reandroid.arsc.chunk.xml.ResXmlElement
15	import java.io.File
16	import java.security.MessageDigest
17	import java.util.zip.ZipFile
18	
19	/** פעולה אמיתית שנשארה "ממתינה" אחרי ריצה מוצלחת ב"בדיקה בלבד" - כדי ש-commit() יוכל לבצע אותה בלי לחזור על כל הצנרת (pull/פירוק/עריכה/הרכבה/חתימה/אימות). */
20	private sealed class PendingCommit {
21	    data class PushFile(val localFile: File, val remotePath: String, val remount: String) : PendingCommit()
22	    data class DeleteFile(val remotePath: String, val remount: String) : PendingCommit()
23	    data class PutSetting(val namespace: String, val key: String, val value: String) : PendingCommit()
24	}
25	
26	/**
27	 * מנוע כללי: מקבל Patch ומבצע את הפעולה המתאימה ל-kind שלו.
28	 * כל שגיאה - כולל חריגה לא צפויה - נתפסת ונרשמת ללוג המלא, לא נופלת בשקט.
29	 * מופע אחד חי לכל חיי ה-Activity (לא נוצר מחדש בכל לחיצה), כדי ש-commit()
30	 * יוכל להסתמך על מה שכבר הוכן ונבדק ב"בדיקה בלבד" הקודמת.
31	 */
32	/**
33	 * לפי בקשה מפורשת של המשתמש (ולפי ניסיון אישי שלו על המכשיר הזה): לא לחתום
34	 * בכלל על קבצים אחרי עריכה, גם לא APK-ים. קוד החתימה (Signer.kt) לא נמחק -
35	 * אם מתברר שצריך אותו בעתיד, להחזיר ל-true זה כל מה שצריך.
36	 */
37	private const val SIGN_EDITED_FILES = true
38	
39	class PatchEngine(
40	    private val context: Context,
41	    private val workDir: File,
42	    private val logger: Logger
43	) {
44	    private val pending = mutableMapOf<String, PendingCommit>()
45	
46	    fun apply(patch: Patch, dryRun: Boolean, log: (String) -> Unit): Boolean {
47	        fun l(msg: String) {
48	            log(msg)
49	            logger.log("[${patch.id}] $msg")
50	        }
51	
52	        return try {
53	            patch.note?.let { l("הערה: $it") }
54	            when (patch.kind) {
55	                "info" -> {
56	                    l("זו עריכה ידנית בלבד - האפליקציה לא מבצעת כאן שום פעולה במכשיר:")
57	                    l(patch.infoText ?: "(אין טקסט הסברה)")
58	                    true
59	                }
60	                "setting" -> applySetting(patch, dryRun, ::l)
61	                "delete" -> applyDelete(patch, dryRun, ::l)
62	                "edit" -> applyEdit(patch, dryRun, ::l)
63	                else -> {
64	                    l("סוג תיקון לא מוכר: ${patch.kind}")
65	                    false
66	                }
67	            }
68	        } catch (e: Throwable) {
69	            l("שגיאה לא צפויה: ${e.message}")
70	            logger.log("[${patch.id}] EXCEPTION:\n${e.stackTraceToString()}")
71	            false
72	        }
73	    }
74	
75	    /**
76	     * מבצע בפועל פעולה שנשארה ממתינה מריצת "בדיקה בלבד" קודמת - בלי לחזור על
77	     * pull/פירוק/עריכה/הרכבה/חתימה/אימות. אם אין פעולה ממתינה (לא רץ עדיין
78	     * "בדיקה בלבד" בהצלחה על התיקון הזה) - נכשל עם הודעה ברורה.
79	     */
80	    fun commit(patch: Patch, log: (String) -> Unit): Boolean {
81	        fun l(msg: String) {
82	            log(msg)
83	            logger.log("[${patch.id}] $msg")
84	        }
85	
86	        val p = pending[patch.id] ?: return false.also {
87	            l("אין פעולה ממתינה לתיקון הזה - צריך להריץ קודם ב'בדיקה בלבד' בהצלחה")
88	        }
89	
90	        val result = when (p) {
91	            is PendingCommit.PushFile -> {
92	                l("מעביר בחזרה למכשיר (מהריצה הקודמת שעברה בדיקה)...")
93	                val (ok, out) = RootShell.push(p.localFile.absolutePath, p.remotePath, p.remount)
94	                logger.log(out)
95	                l(if (ok) "הושלם בהצלחה" else "נכשל בהעברה חזרה - ראה את הלוג המלא")
96	                ok
97	            }
98	            is PendingCommit.DeleteFile -> {
99	                l("מוחק בפועל (מהריצה הקודמת שעברה בדיקה)...")
100	                val (ok, out) = RootShell.deleteFile(p.remotePath, p.remount)
101	                logger.log(out)
102	                l(if (ok) "הושלם" else "נכשל - ראה את הלוג המלא")
103	                ok
104	            }
105	            is PendingCommit.PutSetting -> {
106	                l("קובע settings בפועל...")
107	                val (ok, out) = RootShell.putSetting(p.namespace, p.key, p.value)
108	                logger.log(out)
109	                l(if (ok) "הושלם - נדרש reboot מלא כדי שהשינוי ישפיע" else "נכשל - ראה את הלוג המלא")
110	                ok
111	            }
112	        }
113	        if (result) pending.remove(patch.id)
114	        return result
115	    }
116	
117	    private fun applySetting(patch: Patch, dryRun: Boolean, l: (String) -> Unit): Boolean {
118	        val ns = patch.settingNamespace ?: return false.also { l("חסר settingNamespace") }
119	        val key = patch.settingKey ?: return false.also { l("חסר settingKey") }
120	        val value = patch.settingValue ?: return false.also { l("חסר settingValue") }
121	        if (dryRun) {
122	            l("מצב בדיקה בלבד - לא משנה settings. הפקודה שתרוץ: settings put $ns $key $value")
123	            pending[patch.id] = PendingCommit.PutSetting(ns, key, value)
124	            return true
125	        }
126	        l("קובע $ns/$key = $value ...")
127	        val (ok, out) = RootShell.putSetting(ns, key, value)
128	        logger.log(out)
129	        l(if (ok) "הושלם - נדרש reboot מלא כדי שהשינוי ישפיע" else "נכשל - ראה את הלוג המלא")
130	        return ok
131	    }
132	
133	    private fun applyDelete(patch: Patch, dryRun: Boolean, l: (String) -> Unit): Boolean {
134	        val target = patch.targetFile ?: return false.also { l("חסר targetFile") }
135	        val remount = patch.remount ?: return false.also { l("חסר remount") }
136	
137	        if (RootShell.exists(target)) {
138	            val backupFile = File(context.getExternalFilesDir("backups"), "${patch.id}_${System.currentTimeMillis()}.bak")
139	            backupFile.parentFile?.mkdirs()
140	            val (pulled, pullLog) = RootShell.pull(target, backupFile.absolutePath)
141	            logger.log(pullLog)
142	            if (pulled) l("גיבוי לפני מחיקה נשמר ב: ${backupFile.absolutePath}")
143	            else l("אזהרה: הגיבוי לפני המחיקה נכשל - ממשיך בכל זאת")
144	
145	            if (pulled && !checkExpectedHash(patch, backupFile, l)) return false
146	        } else {
147	            l("הקובץ $target לא קיים כבר - אין מה למחוק")
148	            return true
149	        }
150	
151	        if (dryRun) {
152	            l("מצב בדיקה בלבד - לא נמחק בפועל. היה נמחק: $target")
153	            pending[patch.id] = PendingCommit.DeleteFile(target, remount)
154	            return true
155	        }
156	
157	        l("מוחק את $target ...")
158	        val (ok, out) = RootShell.deleteFile(target, remount)
159	        logger.log(out)
160	        l(if (ok) "הושלם" else "נכשל - ראה את הלוג המלא")
161	        return ok
162	    }
163	
164	    private fun applyEdit(patch: Patch, dryRun: Boolean, l: (String) -> Unit): Boolean {
165	        val target = patch.targetFile ?: return false.also { l("חסר targetFile") }
166	        val remount = patch.remount ?: return false.also { l("חסר remount") }
167	        val signingKey = patch.signingKey
168	        if (SIGN_EDITED_FILES && signingKey == null) return false.also { l("חסר signingKey") }
169	        if (patch.edits.isEmpty() && patch.resourceRemovals.isEmpty()) {
170	            return false.also { l("אין edits ואין resourceRemovals בתיקון הזה") }
171	        }
172	
173	        l("שולף את $target")
174	        val localOriginal = File(workDir, "${patch.id}_original")
175	        val (pulled, pullLog) = RootShell.pull(target, localOriginal.absolutePath)
176	        logger.log(pullLog)
177	        if (!pulled) {
178	            l("נכשל ב-pull - ראה את הלוג המלא")
179	            return false
180	        }
181	
182	        val backupFile = File(context.getExternalFilesDir("backups"), "${patch.id}_${System.currentTimeMillis()}.orig")
183	        backupFile.parentFile?.mkdirs()
184	        localOriginal.copyTo(backupFile, overwrite = true)
185	        l("גיבוי הקובץ המקורי נשמר ב: ${backupFile.absolutePath}")
186	
187	        if (!checkExpectedHash(patch, localOriginal, l)) return false
188	
189	        // patchedZip מתחיל כעותק של המקור, ושתי שכבות העריכה (dex ואז משאבים)
190	        // עובדות ברצף על אותו קובץ - כך שאפשר לשלב את שתיהן בפאץ' אחד על אותו
191	        // קובץ, בלי ששתיהן "יתחרו" זו בזו על hash המקור.
192	        var patchedZip = File(workDir, "${patch.id}_patched.apk")
193	        localOriginal.copyTo(patchedZip, overwrite = true)
194	
195	        if (patch.edits.isNotEmpty()) {
196	            l("מאתר באיזה classes*.dex נמצאות המחלקות הרלוונטיות...")
197	            val found = findDexContaining(patchedZip, patch.edits.map { it.className })
198	            if (found == null) {
199	                l("לא נמצא classes*.dex שמכיל אף אחת מהמחלקות של התיקון הזה - כנראה גרסה לא תואמת")
200	                return false
201	            }
202	            val (dexEntryName, dexLocalFile) = found
203	            l("נמצא ב: $dexEntryName")
204	
205	            val smaliOutDir = File(workDir, "${patch.id}_smali").also { it.deleteRecursively(); it.mkdirs() }
206	            l("מפרק ל-smali...")
207	            val dex = DexFileFactory.loadDexFile(dexLocalFile, Opcodes.getDefault())
208	            Baksmali.disassembleDexFile(dex, smaliOutDir, 1, BaksmaliOptions())
209	
210	            for (edit in patch.edits) {
211	                val classRelPath = edit.className.removePrefix("L").removeSuffix(";") + ".smali"
212	                val smaliFile = File(smaliOutDir, classRelPath)
213	                when (edit.kind) {
214	                    "method" -> {
215	                        if (!smaliFile.exists()) {
216	                            l("לא נמצא קובץ smali למחלקה ${edit.className} - דולג")
217	                            return false
218	                        }
219	                        l("מחליף את ${edit.methodName} ב-${edit.className}...")
220	                        if (!replaceMethod(smaliFile, edit.methodName ?: "", edit.newMethodSmali ?: "")) {
221	                            l("לא נמצאה המתודה ${edit.methodName} - לא בוצע שינוי")
222	                            return false
223	                        }
224	                    }
225	                    "class" -> {
226	                        l("כותב קובץ smali שלם ל-${edit.className} (${if (smaliFile.exists()) "מחליף קיים" else "מחלקה חדשה"})...")
227	                        smaliFile.parentFile?.mkdirs()
228	                        smaliFile.writeText((edit.newClassSmali ?: "").trim() + "\n")
229	                    }
230	                    else -> {
231	                        l("סוג edit לא מוכר: ${edit.kind}")
232	                        return false
233	                    }
234	                }
235	            }
236	
237	            l("מרכיב מחדש ל-dex...")
238	            val newDexFile = File(workDir, "${patch.id}_new.dex")
239	            val smaliOptions = SmaliOptions()
240	            smaliOptions.outputDexFile = newDexFile.absolutePath
241	            val assembled = Smali.assemble(smaliOptions, listOf(smaliOutDir.absolutePath))
242	            if (!assembled) {
243	                l("הרכבה מחדש נכשלה")
244	                return false
245	            }
246	
247	            val afterDex = File(workDir, "${patch.id}_after_dex.apk")
248	            replaceEntryInZip(patchedZip, afterDex, dexEntryName, newDexFile)
249	            patchedZip = afterDex
250	        }
251	
252	        if (patch.resourceRemovals.isNotEmpty()) {
253	            // לשחרר כל מה שעיבוד ה-dex (baksmali/smali) עוד מחזיק לפני שטוענים
254	            // את כל טבלת המשאבים לזיכרון - ARSCLib טוען הכל בבת אחת.
255	            System.gc()
256	            if (!applyResourceRemovals(patch, patchedZip, l)) return false
257	        }
258	
259	        val signedZip: File
260	        if (SIGN_EDITED_FILES && signingKey != null) {
261	            signedZip = File(workDir, "${patch.id}_signed.apk")
262	            l("חותם עם ${patch.signingKey}...")
263	            Signer.sign(context, patchedZip, signedZip, signingKey)
264	            l("קובץ חתום מוכן: ${signedZip.absolutePath} (${signedZip.length()} בייט)")
265	
266	            l("מאמת את החתימה לפני שממשיכים...")
267	            val (verified, verifyLog) = Signer.verify(signedZip)
268	            logger.log(verifyLog)
269	            if (!verified) {
270	                l("אימות החתימה נכשל - לא ממשיכים להחזיר למכשיר, ראה את הלוג המלא")
271	                return false
272	            }
273	            l("החתימה אומתה בהצלחה")
274	        } else {
275	            signedZip = patchedZip
276	            l("ללא חתימה (לפי בחירה מפורשת) - הקובץ יוחזר כמו שהוא, רק ה-dex הוחלף")
277	        }
278	
279	        if (dryRun) {
280	            l("מצב בדיקה בלבד - לא הוחזר למכשיר")
281	            pending[patch.id] = PendingCommit.PushFile(signedZip, target, remount)
282	            return true
283	        }
284	
285	        l("מעביר בחזרה למכשיר...")
286	        val (pushed, pushLog) = RootShell.push(signedZip.absolutePath, target, remount)
287	        logger.log(pushLog)
288	        l(if (pushed) "הושלם בהצלחה" else "נכשל בהעברה חזרה - ראה את הלוג המלא")
289	        return pushed
290	    }
291	
292	    /**
293	     * מסיר אלמנטי Preference (או כל אלמנט עם android:key) ממשאבי XML בינאריים
294	     * בתוך ה-APK, לפי (path, key) - בלי apktool/PC, עם ARSCLib. דורס את
295	     * patchedZip בקובץ חדש; patch.resourceRemovals מגיע מ-patchedZip ולא
296	     * מ-localOriginal, כך שאפשר לשלב את זה עם עריכות dex על אותו קובץ.
297	     */
298	    private fun applyResourceRemovals(patch: Patch, patchedZip: File, l: (String) -> Unit): Boolean {
299	        l("עורך משאבים בינאריים (${patch.resourceRemovals.size} הסרות)...")
300	        val module = ApkModule.loadApkFile(patchedZip)
301	        var totalRemoved = 0
302	        // מסמך אחד לכל קובץ: getResXmlDocument מחזיר עותק חדש בכל קריאה, ועריכות על עותק קודם היו נעלמות.
303	        val docs = LinkedHashMap<String, ResXmlDocument>()
304	        for (removal in patch.resourceRemovals) {
305	            val doc = docs[removal.path] ?: module.getResXmlDocument(removal.path)?.also { docs[removal.path] = it }
306	            if (doc == null) {
307	                l("לא נמצא קובץ משאב: ${removal.path} - דולג")
308	                continue
309	            }
310	            val targets = mutableListOf<ResXmlElement>()
311	            val it = doc.recursiveElements()
312	            while (it.hasNext()) {
313	                val e = it.next()
314	                val attr: ResXmlAttribute? = e.searchAttributeByName("key")
315	                if (attr != null && removal.key == attr.valueString) targets.add(e)
316	            }
317	            if (targets.isEmpty()) {
318	                l("לא נמצא key=\"${removal.key}\" ב-${removal.path} - דולג")
319	                continue
320	            }
321	            for (t in targets) t.removeSelf()
322	            l("הוסר key=\"${removal.key}\" מתוך ${removal.path} (${targets.size})")
323	            totalRemoved += targets.size
324	        }
325	        if (totalRemoved == 0) {
326	            l("אף הסרה לא בוצעה בפועל - לא ממשיכים")
327	            return false
328	        }
329	        // בלי refresh() כותרת הגודל של ה-XML נשארת ישנה והקובץ לא ניתן לקריאה.
330	        for ((path, doc) in docs) {
331	            doc.refresh()
332	            module.add(ByteInputSource(doc.bytes, path))
333	        }
334	        val afterResources = File(workDir, "${patch.id}_after_res.apk")
335	        module.writeApk(afterResources)
336	        ZipUtil.alignInPlace(afterResources)
337	        afterResources.copyTo(patchedZip, overwrite = true)
338	        l("עריכת המשאבים הושלמה (${totalRemoved} אלמנטים הוסרו בסה\"כ)")
339	        return true
340	    }
341	
342	    /** משחזר קובץ גיבוי בחזרה לנתיב המקורי שלו - החזרה חזרה בודדת, בלי לגעת בשום dex. */
343	    fun restore(backupFile: File, targetFile: String, remount: String, log: (String) -> Unit): Boolean {
344	        fun l(msg: String) {
345	            log(msg)
346	            logger.log("[restore] $msg")
347	        }
348	        l("משחזר את ${backupFile.name} בחזרה אל $targetFile ...")
349	        val (ok, out) = RootShell.push(backupFile.absolutePath, targetFile, remount)
350	        logger.log(out)
351	        l(if (ok) "השחזור הושלם" else "השחזור נכשל - ראה את הלוג המלא")
352	        return ok
353	    }
354	
355	    /**
356	     * מוודא שהקובץ שנשלף הוא בדיוק הקובץ שהתיקון הזה אומת מולו, *לפני* שנוגעים
357	     * בו - לפי בקשה מפורשת: לבדוק זהות אחד-לאחד לקובץ מוכר ורק אז להחליף.
358	     * אם expectedSha256 לא מוגדר בתיקון, אין בדיקה (לא כל תיקון יש לו עוד hash
359	     * מאומת - למשל M393 שהנתיב שלו עדיין לא אומת כלל).
360	     */
361	    private fun checkExpectedHash(patch: Patch, file: File, l: (String) -> Unit): Boolean {
362	        val expected = patch.expectedSha256 ?: return true
363	        val actual = sha256(file)
364	        if (actual.equals(expected, ignoreCase = true)) {
365	            l("בדיקת SHA-256 עברה - זה בדיוק הקובץ שהתיקון אומת מולו")
366	            return true
367	        }
368	        l("עצירה: ה-SHA-256 של הקובץ לא תואם למה שהתיקון הזה אומת מולו - לא ממשיך")
369	        l("  צפוי:  $expected")
370	        l("  בפועל: $actual")
371	        l("  (קובץ שונה/גרסה אחרת/קובץ שכבר תוקן בעבר - לא מניחים שההחלפה בטוחה)")
372	        return false
373	    }
374	
375	    private fun sha256(file: File): String {
376	        val digest = MessageDigest.getInstance("SHA-256")
377	        file.inputStream().use { input ->
378	            val buf = ByteArray(8192)
379	            while (true) {
380	                val n = input.read(buf)
381	                if (n < 0) break
382	                digest.update(buf, 0, n)
383	            }
384	        }
385	        return digest.digest().joinToString("") { "%02x".format(it) }
386	    }
387	
388	    /** סורק את כל ה-classes*.dex בתוך ה-zip ומחזיר את הראשון שמכיל אחת מהמחלקות הנתונות. */
389	    private fun findDexContaining(zipFile: File, classNames: List<String>): Pair<String, File>? {
390	        ZipFile(zipFile).use { zf ->
391	            val dexEntryNames = zf.entries().asSequence()
392	                .map { it.name }
393	                .filter { it.matches(Regex("""classes\d*\.dex""")) }
394	                .sorted()
395	                .toList()
396	
397	            for (name in dexEntryNames) {
398	                val tmp = File(workDir, "probe_${name.replace('/', '_')}")
399	                zf.getInputStream(zf.getEntry(name)).use { input ->
400	                    tmp.outputStream().use { output -> input.copyTo(output) }
401	                }
402	                val dex = DexFileFactory.loadDexFile(tmp, Opcodes.getDefault())
403	                val hasAny = dex.classes.any { it.type in classNames }
404	                if (hasAny) return name to tmp
405	            }
406	        }
407	        return null
408	    }
409	
410	    private fun replaceEntryInZip(src: File, dst: File, entryName: String, newEntryContent: File) {
411	        ZipUtil.rewrite(src, dst, mapOf(entryName to newEntryContent))
412	    }
413	    /**
414	     * מחליף טקסטואלית מתודה שלמה (מ-".method ... methodName" ועד ה-".end method"
415	     * התואם) - בדיוק השיטה שהשתמשנו בה ידנית ב-MT Manager, רק אוטומטית.
416	     */
417	    private fun replaceMethod(smaliFile: File, methodName: String, newMethodBody: String): Boolean {
418	        val text = smaliFile.readText()
419	        val startRegex = Regex("""\.method[^\n]*\s$methodName\(""")
420	        val match = startRegex.find(text) ?: return false
421	        val methodStart = text.lastIndexOf(".method", match.range.first)
422	        val endIdx = text.indexOf(".end method", match.range.last)
423	        if (methodStart == -1 || endIdx == -1) return false
424	        val afterEnd = endIdx + ".end method".length
425	        val newText = text.substring(0, methodStart) + newMethodBody.trim() + text.substring(afterEnd)
426	        smaliFile.writeText(newText)
427	        return true
428	    }
429	}
