1	package com.orech.patcher
2	
3	import java.io.BufferedOutputStream
4	import java.io.File
5	import java.io.FilterOutputStream
6	import java.io.OutputStream
7	import java.util.zip.CRC32
8	import java.util.zip.ZipEntry
9	import java.util.zip.ZipFile
10	import java.util.zip.ZipOutputStream
11	
12	/**
13	 * כתיבה מחדש של zip בלי לאבד את שיטת הדחיסה של כל רשומה, ועם יישור ל-4 בתים של רשומות
14	 * לא דחוסות (resources.arsc חייב להיות לא דחוס ומיושר באפליקציות שמכוונות ל-R ומעלה).
15	 * נבדק מול zipalign -c על שלושה APK שלא היו מיושרים.
16	 */
17	object ZipUtil {
18	
19	    private class CountingOutputStream(out: OutputStream) : FilterOutputStream(out) {
20	        var count = 0L
21	        override fun write(b: Int) { out.write(b); count++ }
22	        override fun write(b: ByteArray, off: Int, len: Int) { out.write(b, off, len); count += len }
23	    }
24	
25	    /** מחליף רשומות לפי שם (replacements) ומיישר את כל השאר. הפלט נכתב ל-dst. */
26	    fun rewrite(src: File, dst: File, replacements: Map<String, File> = emptyMap(), alignment: Int = 4) {
27	        ZipFile(src).use { zf ->
28	            val counting = CountingOutputStream(BufferedOutputStream(dst.outputStream()))
29	            ZipOutputStream(counting).use { zos ->
30	                val entries = zf.entries()
31	                while (entries.hasMoreElements()) {
32	                    val e = entries.nextElement()
33	                    val replacement = replacements[e.name]
34	                    val ne = ZipEntry(e.name)
35	                    ne.time = e.time
36	                    if (e.method == ZipEntry.STORED) {
37	                        ne.method = ZipEntry.STORED
38	                        if (replacement != null) {
39	                            val crc = CRC32()
40	                            replacement.inputStream().use { input ->
41	                                val buf = ByteArray(64 * 1024)
42	                                while (true) {
43	                                    val n = input.read(buf)
44	                                    if (n <= 0) break
45	                                    crc.update(buf, 0, n)
46	                                }
47	                            }
48	                            ne.size = replacement.length()
49	                            ne.compressedSize = replacement.length()
50	                            ne.crc = crc.value
51	                        } else {
52	                            ne.size = e.size
53	                            ne.compressedSize = e.size
54	                            ne.crc = e.crc
55	                        }
56	                        val nameLen = e.name.toByteArray(Charsets.UTF_8).size
57	                        val dataOffset = counting.count + 30 + nameLen
58	                        var pad = ((alignment - (dataOffset % alignment)) % alignment).toInt()
59	                        if (pad > 0) {
60	                            if (pad < 4) pad += 4
61	                            val extra = ByteArray(pad)
62	                            extra[0] = 0xD9.toByte()
63	                            extra[1] = 0x35
64	                            extra[2] = ((pad - 4) and 0xFF).toByte()
65	                            extra[3] = (((pad - 4) shr 8) and 0xFF).toByte()
66	                            ne.extra = extra
67	                        }
68	                    }
69	                    zos.putNextEntry(ne)
70	                    if (replacement != null) {
71	                        replacement.inputStream().use { it.copyTo(zos) }
72	                    } else {
73	                        zf.getInputStream(e).use { it.copyTo(zos) }
74	                    }
75	                    zos.closeEntry()
76	                }
77	            }
78	        }
79	    }
80	
81	    /** יישור במקום: כותב לקובץ זמני ומחליף. */
82	    fun alignInPlace(file: File) {
83	        val tmp = File(file.parentFile, file.name + ".aligned")
84	        rewrite(file, tmp)
85	        tmp.copyTo(file, overwrite = true)
86	        tmp.delete()
87	    }
88	}
