1	package com.orech.patcher
2	
3	import android.content.Context
4	import com.android.tools.smali.baksmali.Baksmali
5	import com.android.tools.smali.baksmali.BaksmaliOptions
6	import com.android.tools.smali.dexlib2.DexFileFactory
7	import com.android.tools.smali.dexlib2.Opcodes
8	import com.android.tools.smali.smali.Smali
9	import com.android.tools.smali.smali.SmaliOptions
10	import com.reandroid.apk.ApkModule
11	import com.reandroid.archive.ByteInputSource
12	import com.reandroid.arsc.chunk.xml.ResXmlDocument
13	import com.reandroid.arsc.chunk.xml.ResXmlAttribute
14	import com.reandroid.arsc.chunk.xml.ResXmlElement
15	import java.io.File
16	import java.security.MessageDigest
17	import java.util.zip.ZipFile
18	
19	/** פעולה אמיתית שנשארה "ממתינה" אחרי ריצה מוצלחת ב"בדיקה בלבד" - כדי ש-commit() יוכל לבצע אותה בלי לחזור על כל הצנרת (pull/פירוק/עריכה/הרכבה/חתימה/אימות). */
20	private sealed class PendingCommit {
21	    data class PushFile(val localFile: File, val remotePath: String, val remount: String) : PendingCommit()
22	    data class DeleteFile(val remotePath: String, val remount: String) : PendingCommit()
23	    data class PutSetting(val namespace: String, val key: String, val value: String) : PendingCommit()
24	}
25	
26	/**
27	 * מנוע כללי: מקבל Patch ומבצע את הפעולה המתאימה ל-kind שלו.
28	 * כל שגיאה - כולל חריגה לא צפויה - נתפסת ונרשמת ללוג המלא, לא נופלת בשקט.
29	 * מופע אחד חי לכל חיי ה-Activity (לא נוצר מחדש בכל לחיצה), כדי ש-commit()
30	 * יוכל להסתמך על מה שכבר הוכן ונבדק ב"בדיקה בלבד" הקודמת.
31	 */
32	/**
33	 * לפי בקשה מפורשת של המשתמש (ולפי ניסיון אישי שלו על המכשיר הזה): לא לחתום
34	 * בכלל על קבצים אחרי עריכה, גם לא APK-ים. קוד החתימה (Signer.kt) לא נמחק -
35	 * אם מתברר שצריך אותו בעתיד, להחזיר ל-true זה כל מה שצריך.
36	 */
37	private const val SIGN_EDITED_FILES = true
38	
39	class PatchEngine(
40	    private val context: Context,
41	    private val workDir: File,
42	    private val logger: Logger
43	) {
44	    private val pending = mutableMapOf<String, PendingCommit>()
45	
46	    fun apply(patch: Patch, dryRun: Boolean, log: (String) -> Unit): Boolean {
