81	        fun l(msg: String) {
82	            log(msg)
83	            logger.log("[${patch.id}] $msg")
84	        }
85	
86	        val p = pending[patch.id] ?: return false.also {
87	            l("אין פעולה ממתינה לתיקון הזה - צריך להריץ קודם ב'בדיקה בלבד' בהצלחה")
