292	    /**
293	     * מסיר אלמנטי Preference (או כל אלמנט עם android:key) ממשאבי XML בינאריים
294	     * בתוך ה-APK, לפי (path, key) - בלי apktool/PC, עם ARSCLib. דורס את
295	     * patchedZip בקובץ חדש; patch.resourceRemovals מגיע מ-patchedZip ולא
296	     * מ-localOriginal, כך שאפשר לשלב את זה עם עריכות dex על אותו קובץ.
297	     */
298	    private fun applyResourceRemovals(patch: Patch, patchedZip: File, l: (String) -> Unit): Boolean {
299	        l("עורך משאבים בינאריים (${patch.resourceRemovals.size} הסרות)...")
300	        val module = ApkModule.loadApkFile(patchedZip)
301	        var totalRemoved = 0
302	        // מסמך אחד לכל קובץ: getResXmlDocument מחזיר עותק חדש בכל קריאה, ועריכות על עותק קודם היו נעלמות.
303	        val docs = LinkedHashMap<String, ResXmlDocument>()
304	        for (removal in patch.resourceRemovals) {
305	            val doc = docs[removal.path] ?: module.getResXmlDocument(removal.path)?.also { docs[removal.path] = it }
306	            if (doc == null) {
307	                l("לא נמצא קובץ משאב: ${removal.path} - דולג")
308	                continue
309	            }
310	            val targets = mutableListOf<ResXmlElement>()
311	            val it = doc.recursiveElements()
312	            while (it.hasNext()) {
313	                val e = it.next()
314	                val attr: ResXmlAttribute? = e.searchAttributeByName("key")
315	                if (attr != null && removal.key == attr.valueString) targets.add(e)
316	            }
317	            if (targets.isEmpty()) {
318	                l("לא נמצא key=\"${removal.key}\" ב-${removal.path} - דולג")
319	                continue
320	            }
321	            for (t in targets) t.removeSelf()
322	            l("הוסר key=\"${removal.key}\" מתוך ${removal.path} (${targets.size})")
323	            totalRemoved += targets.size
324	        }
325	        if (totalRemoved == 0) {
326	            l("אף הסרה לא בוצעה בפועל - לא ממשיכים")
327	            return false
328	        }
329	        // בלי refresh() כותרת הגודל של ה-XML נשארת ישנה והקובץ לא ניתן לקריאה.
330	        for ((path, doc) in docs) {
331	            doc.refresh()
332	            module.add(ByteInputSource(doc.bytes, path))
333	        }
334	        val afterResources = File(workDir, "${patch.id}_after_res.apk")
335	        module.writeApk(afterResources)
336	        ZipUtil.alignInPlace(afterResources)
337	        afterResources.copyTo(patchedZip, overwrite = true)
338	        l("עריכת המשאבים הושלמה (${totalRemoved} אלמנטים הוסרו בסה\"כ)")
339	        return true
340	    }
