388	    /** סורק את כל ה-classes*.dex בתוך ה-zip ומחזיר את הראשון שמכיל אחת מהמחלקות הנתונות. */
389	    private fun findDexContaining(zipFile: File, classNames: List<String>): Pair<String, File>? {
390	        ZipFile(zipFile).use { zf ->
391	            val dexEntryNames = zf.entries().asSequence()
392	                .map { it.name }
393	                .filter { it.matches(Regex("""classes\d*\.dex""")) }
394	                .sorted()
395	                .toList()
396	
397	            for (name in dexEntryNames) {
398	                val tmp = File(workDir, "probe_${name.replace('/', '_')}")
399	                zf.getInputStream(zf.getEntry(name)).use { input ->
400	                    tmp.outputStream().use { output -> input.copyTo(output) }
401	                }
402	                val dex = DexFileFactory.loadDexFile(tmp, Opcodes.getDefault())
403	                val hasAny = dex.classes.any { it.type in classNames }
404	                if (hasAny) return name to tmp
405	            }
406	        }
407	        return null
408	    }
