413	    /**
414	     * מחליף טקסטואלית מתודה שלמה (מ-".method ... methodName" ועד ה-".end method"
415	     * התואם) - בדיוק השיטה שהשתמשנו בה ידנית ב-MT Manager, רק אוטומטית.
416	     */
417	    private fun replaceMethod(smaliFile: File, methodName: String, newMethodBody: String): Boolean {
418	        val text = smaliFile.readText()
419	        val startRegex = Regex("""\.method[^\n]*\s$methodName\(""")
420	        val match = startRegex.find(text) ?: return false
421	        val methodStart = text.lastIndexOf(".method", match.range.first)
422	        val endIdx = text.indexOf(".end method", match.range.last)
423	        if (methodStart == -1 || endIdx == -1) return false
424	        val afterEnd = endIdx + ".end method".length
425	        val newText = text.substring(0, methodStart) + newMethodBody.trim() + text.substring(afterEnd)
426	        smaliFile.writeText(newText)
427	        return true
428	    }
