        } catch (Throwable t) {
            return false;
        } finally {
            try { if (z != null) z.close(); } catch (Throwable ignored) { }
        }
        return false;
    }

    private static boolean manifestDeclaresVideo(ZipFile z, ZipEntry en) throws Exception {
        InputStream in = z.getInputStream(en);
        try {
            byte[] buf = new byte[(int) Math.max(en.getSize(), 1024)];
            int len = 0;
            int r;
            while ((r = in.read(buf, len, buf.length - len)) > 0) {
                len += r;
                if (len == buf.length) {
                    byte[] nb = new byte[buf.length * 2];
                    System.arraycopy(buf, 0, nb, 0, len);
                    buf = nb;
                }
            }
            // string pool is UTF-8 or UTF-16LE: look for "video/" in both
            byte[] u8 = {'v', 'i', 'd', 'e', 'o', '/'};
            byte[] u16 = {'v', 0, 'i', 0, 'd', 0, 'e', 0, 'o', 0, '/', 0};
            if (indexOf(buf, len, u8) >= 0 || indexOf(buf, len, u16) >= 0) return true;
            // apps that can install other apps (REQUEST_INSTALL_PACKAGES / INSTALL_PACKAGES)
            byte[] i8 = "INSTALL_PACKAGES".getBytes("US-ASCII");
            byte[] i16 = new byte[i8.length * 2];
            for (int k = 0; k < i8.length; k++) { i16[k * 2] = i8[k]; i16[k * 2 + 1] = 0; }
            return indexOf(buf, len, i8) >= 0 || indexOf(buf, len, i16) >= 0;
        } finally {
            in.close();
        }
    }

    private static int indexOf(byte[] h, int hl, byte[] n) {
        outer:
        for (int i = 0; i + n.length <= hl; i++) {
            for (int j = 0; j < n.length; j++) {
                if (h[i + j] != n[j]) continue outer;
            }
            return i;
        }
        return -1;
    }
}
