            row.addView(tileView(tiles.get(i)), Ui.margins(Ui.lp(0, Ui.WRAP, 1), 5, 5, 5, 5));
        }
        int rest = tiles.size() % cols;
        if (rest != 0) for (int i = rest; i < cols; i++) row.addView(new View(a), Ui.margins(Ui.lp(0, 1, 1), 5, 5, 5, 5));
